void __fastcall D2MEM_CopyRows(char * pCharSelComp, uint8_t * pSrc, int32_t nDstStride, int32_t nSrcStride, int32_t nRows, uint32_t nBytesPerRow) {
    do {
      uint32_t nRemainder;
      nRemainder = nBytesPerRow & 3;
      if (nRemainder) {
        switch (nRemainder) {
          case 1:
            {
              *pCharSelComp = *pSrc;
              pCharSelComp++;
              pSrc++;
              break;
            }
          case 2:
            {
              *pCharSelComp = *pSrc;
              pCharSelComp[1] = pSrc[1];
              pCharSelComp += 2;
              pSrc += 2;
              break;
            }
          default:
            {
              *pCharSelComp = *pSrc;
              pCharSelComp[1] = pSrc[1];
              pCharSelComp[2] = pSrc[2];
              pCharSelComp += 3;
              pSrc += 3;
            }
        }
      }

      for (nRemainder = nBytesPerRow >> 2; nRemainder; nRemainder--) {
        *(uint32_t*)pCharSelComp = *(uint32_t*)pSrc;
        pSrc += 4;
        pCharSelComp += 4;
      }

      pSrc += nSrcStride - nBytesPerRow;
      pCharSelComp += nDstStride - nBytesPerRow;
      nRows--;
    } while (nRows);
}

uint32_t __fastcall D2MEM_CompareBytes(uint8_t * pBuf1, uint8_t * pBuf2, uint32_t nByteCount) {
    uint32_t nRemainder = nByteCount & 3;
    if (nRemainder) {
      switch (nRemainder) {
        case 1:
          {
            if (*pBuf2 != *pBuf1) {
              return 0;
            }

            pBuf1++;
            pBuf2++;
            break;
          }
        case 2:
          {
            if (*pBuf2 != *pBuf1) {
              return 0;
            }
            if (pBuf2[1] != pBuf1[1]) {
              return 0;
            }

            pBuf1 += 2;
            pBuf2 += 2;
            break;
          }
        default:
          {
            if (*pBuf2 != *pBuf1) {
              return 0;
            }
            if (pBuf2[1] != pBuf1[1]) {
              return 0;
            }
            if (pBuf2[2] != pBuf1[2]) {
              return 0;
            }

            pBuf1 += 3;
            pBuf2 += 3;
          }
      }
    }

    nRemainder = nByteCount >> 2;
    bool bEqual = !nRemainder;
    do {
      if (!nRemainder) {
        break;
      }

      nRemainder--;
      bEqual = *(int*)pBuf2 == *(int*)pBuf1;
      pBuf2 = (uint8_t*)((char*)pBuf2 + 4);
      pBuf1 = (uint8_t*)((char*)pBuf1 + 4);
    } while (bEqual);

    if (bEqual) {
      return 1;
    }

    return 0;
}

